import gzip
import json
import re
from hashlib import sha256
from pathlib import Path

import numpy as np
import pandas as pd
import yaml
from pandas.tseries.holiday import (
    AbstractHolidayCalendar,
    GoodFriday,
    Holiday,
    USLaborDay,
    USMartinLutherKingJr,
    USMemorialDay,
    USPresidentsDay,
    USThanksgivingDay,
    nearest_workday,
    sunday_to_monday,
)
from scipy.optimize import minimize
from sklearn.covariance import ledoit_wolf
from threadpoolctl import threadpool_limits


ROOT = Path(__file__).resolve().parent
PRICE_ADJUSTMENT = "yfinance auto_adjust total-return adjusted daily close"
SESSIONS_PER_YEAR = 252
WEIGHT_TOLERANCE = 1e-10


class NYSECalendar(AbstractHolidayCalendar):
    rules = [
        Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
        USMartinLutherKingJr,
        USPresidentsDay,
        GoodFriday,
        USMemorialDay,
        Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
        Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
        USLaborDay,
        USThanksgivingDay,
        Holiday("Christmas", month=12, day=25, observance=nearest_workday),
    ]


# Full-market closures in the data window: Hurricane Sandy and national days of mourning.
NYSE_SPECIAL_CLOSURES = pd.to_datetime(["2012-10-29", "2012-10-30", "2018-12-05", "2025-01-09"])


def load_config(config_path=None):
    path = Path(config_path) if config_path else (ROOT / "config.yaml")
    with open(path, "rb") as source:
        config = yaml.safe_load(source)
    date_keys = ("download_start", "backtest_start", "oos_start", "end")
    for key in date_keys:
        config[key] = pd.Timestamp(config[key])
    download_start, start, split, end = (config[key] for key in date_keys)
    if not download_start < start < split <= end:
        raise ValueError("Dates must satisfy download_start < backtest_start < oos_start <= end.")
    universe = config["universe"]
    if len(universe) < 2 or len(universe) != len(set(universe)):
        raise ValueError("The stock universe must contain at least two distinct tickers.")
    if not all(re.fullmatch(r"[A-Z]{1,5}(?:-[A-Z])?", ticker) for ticker in universe):
        raise ValueError("Use U.S. equity tickers such as MSFT or BRK-B.")
    if config["risk_free_ticker"] != "BIL" or "BIL" in universe:
        raise ValueError("Use BIL outside the stock universe as the cash proxy.")
    for key, minimum in (("lookback_sessions", 2), ("execution_lag_sessions", 1)):
        if type(config[key]) is not int or config[key] < minimum:
            raise ValueError(f"{key} must be an integer of at least {minimum}.")
    for key in ("cost_bps", "slippage_bps", "fourth_moment_penalty"):
        if not np.isfinite(config[key]) or config[key] < 0:
            raise ValueError(f"{key} must be finite and nonnegative.")
    if config["cost_bps"] + config["slippage_bps"] >= 10_000:
        raise ValueError("Cost and slippage together must be under 10,000 bps.")
    if not 0 < config["cash_buffer_bps"] < 10_000:
        raise ValueError("cash_buffer_bps must be above zero and under 10,000 bps.")
    return config


def check_prices(prices, tickers, start, end):
    if prices.empty or not prices.index.is_unique or not prices.index.is_monotonic_increasing:
        raise ValueError("Price data require a nonempty, ordered set of unique sessions.")
    if list(prices.columns) != tickers:
        raise ValueError("Price columns do not match the configured tickers.")
    closures = NYSECalendar().holidays(start, end).union(NYSE_SPECIAL_CLOSURES)
    expected = pd.date_range(start, end, freq="B").difference(closures)
    missing = expected.difference(prices.index)
    if len(missing):
        raise ValueError(f"Missing price data for NYSE session {missing[0].date()}.")
    unexpected = prices.index.difference(expected)
    if len(unexpected):
        raise ValueError(f"Unexpected session in price data: {unexpected[0].date()}.")
    valid = np.isfinite(prices) & (prices > 0)
    if not valid.to_numpy().all():
        row, column = np.argwhere(~valid.to_numpy())[0]
        raise ValueError(f"Missing or invalid close for {tickers[column]} on {prices.index[row].date()}.")


def load_prices(tickers, start, end, settings, config_path="config.yaml"):
    data = settings.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = gzip.decompress(bytes(blob))
    digest = sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the market snapshot in {Path(config_path).name}: {digest}."
        )
    cached = json.loads(snapshot)
    fetched_at = cached["fetched_at"]
    sessions = pd.to_datetime(cached["sessions"]).as_unit("ns")
    prices = pd.DataFrame(cached["closes"], index=sessions, columns=cached["tickers"])
    prices = prices.reindex(columns=tickers)
    check_prices(prices, tickers, start, end)
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: yfinance auto_adjust snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); the script does not call yfinance or read data_cache."
    )
    print(f"Input SHA-256: {digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    return prices, fetched_at


def minimize_moments(window, equal_weights, penalty):
    centered = window - window.mean(axis=0)
    scale = np.sqrt(np.mean((centered @ equal_weights) ** 2))
    if not np.isfinite(scale) or scale <= 0:
        raise ValueError("The trailing variance of the equal-weight basket must be positive.")
    scaled = centered / scale
    covariance, _ = ledoit_wolf(scaled, assume_centered=True)

    def objective(weights):
        cov_product = covariance @ weights
        projected = scaled @ weights
        cubes = projected ** 3
        moment = np.mean(projected * cubes)
        gradient = 2 * cov_product + 4 * penalty * (scaled.T @ cubes) / len(scaled)
        return weights @ cov_product + penalty * moment, gradient

    solution = minimize(
        objective,
        equal_weights,
        jac=True,
        method="SLSQP",
        bounds=[(0, 1)] * len(equal_weights),
        constraints={
            "type": "eq",
            "fun": lambda weights: weights.sum() - 1,
            "jac": lambda weights: np.ones_like(weights),
        },
        options={"ftol": 1e-11, "maxiter": 250},
    )
    weights = solution.x
    if not solution.success or not np.isfinite(weights).all():
        raise RuntimeError(f"Portfolio optimization failed: {solution.message}")
    if abs(weights.sum() - 1) > 1e-8 or weights.min() < -WEIGHT_TOLERANCE:
        raise RuntimeError("Portfolio optimization produced infeasible weights.")
    weights = np.where(weights > WEIGHT_TOLERANCE, weights, 0.0)
    return weights / weights.sum()


def build_targets(asset_returns, config, penalties):
    dates = asset_returns.index
    row_numbers = pd.Series(np.arange(len(dates)), index=dates)
    month_ends = row_numbers.groupby(dates.to_period("M")).last()
    lookback = config["lookback_sessions"]
    lag = config["execution_lag_sessions"]
    equal_weights = np.full(asset_returns.shape[1], 1 / asset_returns.shape[1])
    targets_by_penalty = {penalty: {} for penalty in penalties}
    benchmark_targets = {}
    with threadpool_limits(limits=1, user_api="blas"):
        for signal_row in month_ends:
            window_start = signal_row - lookback + 1
            fill_row = signal_row + lag
            if window_start < 0 or fill_row >= len(dates):
                continue
            fill_date = dates[fill_row]
            if fill_date < config["backtest_start"]:
                continue
            window = asset_returns.iloc[window_start:signal_row + 1].to_numpy()
            for penalty, targets in targets_by_penalty.items():
                try:
                    targets[fill_date] = minimize_moments(window, equal_weights, penalty)
                except (ValueError, RuntimeError) as error:
                    raise RuntimeError(f"Signal on {dates[signal_row].date()} failed for gamma={penalty}.") from error
            benchmark_targets[fill_date] = equal_weights
    return targets_by_penalty, benchmark_targets


def size_rebalance(positions, cash, sizing_close, target, cost_rate, cash_buffer_rate):
    """Lock next-session share changes using the sizing session's close."""
    previous_values = positions * sizing_close
    previous_value = cash + previous_values.sum()
    if not np.isfinite(previous_value) or previous_value <= 0:
        raise RuntimeError("Sizing requires a finite, positive portfolio value.")
    # Budget both sides at the sizing close and leave a reserve for price moves.
    reserve = previous_value * cash_buffer_rate
    value_changes = (previous_value - reserve) * target - previous_values
    value_changes[np.abs(value_changes) <= WEIGHT_TOLERANCE * previous_value] = 0.0
    sells = np.minimum(np.maximum(-value_changes / sizing_close, 0.0), positions)
    buys = np.maximum(value_changes / sizing_close, 0.0)
    buy_budget = max(0.0, cash + (sells @ sizing_close) * (1 - cost_rate) - reserve)
    buy_cost = (buys @ sizing_close) * (1 + cost_rate)
    if buy_cost > buy_budget:
        buys *= buy_budget / buy_cost
    changes = buys - sells
    if not np.isfinite(changes).all():
        raise RuntimeError("Sizing produced non-finite share changes.")
    changes.setflags(write=False)
    return changes


def settle_rebalance(locked_changes, fill_close, cash, cost_rate):
    """Price the fixed batch at the fill close and require finite, nonnegative cash."""
    sold = np.maximum(-locked_changes, 0.0) @ fill_close
    bought = np.maximum(locked_changes, 0.0) @ fill_close
    traded = bought + sold
    cash_after_fill = cash + (sold * (1 - cost_rate) - bought * (1 + cost_rate))
    if not np.isfinite(traded) or not np.isfinite(cash_after_fill):
        raise RuntimeError("Predetermined shares produced a non-finite settlement amount.")
    if cash_after_fill < 0:
        raise RuntimeError(
            f"Predetermined shares require more cash at the close (shortfall {-cash_after_fill:.8g})."
        )
    return cash_after_fill, traded


def simulate(closes, targets, start, cost_rate, cash_buffer_rate):
    positions = np.zeros(closes.shape[1])
    cash = previous_value = 1.0
    dates = closes.index
    close_values = closes.to_numpy()
    first_row = dates.searchsorted(start)
    if first_row == 0 and len(dates) and dates[0] in targets:
        raise ValueError("A rebalance requires a previous session's close.")

    pending_changes = None
    rows = []
    for row in range(max(0, first_row - 1), len(dates)):
        date = dates[row]
        close = close_values[row]
        if row >= first_row:
            turnover, n_trades = 0.0, 0
            if pending_changes is not None:
                value_before_fill = cash + positions @ close
                if not np.isfinite(value_before_fill) or value_before_fill <= 0:
                    raise RuntimeError(f"Invalid portfolio value before the fill on {date.date()}.")
                try:
                    cash_after_fill, traded = settle_rebalance(pending_changes, close, cash, cost_rate)
                except RuntimeError as error:
                    raise RuntimeError(f"Rebalance on {date.date()} stopped: {error}") from error
                positions_after_fill = positions + pending_changes
                if not np.isfinite(positions_after_fill).all() or (positions_after_fill < 0).any():
                    raise RuntimeError(f"Rebalance on {date.date()} produced invalid long-only positions.")
                cash, positions = cash_after_fill, positions_after_fill
                turnover = traded / value_before_fill
                n_trades = np.count_nonzero(pending_changes)

            value = cash + positions @ close
            if not np.isfinite(value) or value <= 0:
                raise RuntimeError(f"Invalid closing portfolio value on {date.date()}.")
            rows.append((value / previous_value - 1, turnover, n_trades))
            previous_value = value

        if row + 1 == len(dates):
            break
        # Lock the next session's quantities after today's close and settlement.
        next_target = targets.get(dates[row + 1])
        pending_changes = None
        if next_target is not None:
            try:
                pending_changes = size_rebalance(positions, cash, close, next_target, cost_rate, cash_buffer_rate)
            except RuntimeError as error:
                raise RuntimeError(f"Sizing after the close on {date.date()} stopped: {error}") from error
    return pd.DataFrame(rows, index=dates[first_row:], columns=["return", "turnover", "n_trades"])


def metrics(daily_results, cash_returns):
    daily = daily_results["return"].to_numpy()
    n_sessions = len(daily)
    excess = daily - cash_returns.loc[daily_results.index].to_numpy()
    growth = np.r_[1.0, np.cumprod(1 + daily)]

    def sharpe(returns):
        if n_sessions < 2 or np.ptp(returns) == 0:
            return None
        volatility = returns.std(ddof=1)
        return float(np.sqrt(SESSIONS_PER_YEAR) * returns.mean() / volatility) if volatility > 0 else None

    return {
        "cagr": float(growth[-1] ** (SESSIONS_PER_YEAR / n_sessions) - 1) if n_sessions else None,
        "ann_vol": float(daily.std(ddof=1) * np.sqrt(SESSIONS_PER_YEAR)) if n_sessions > 1 else None,
        "sharpe": sharpe(daily),
        "sharpe_excess": sharpe(excess),
        "max_drawdown": float(np.min(growth / np.maximum.accumulate(growth) - 1)) if n_sessions else None,
        "total_return": float(growth[-1] - 1) if n_sessions else None,
        "turnover": float(SESSIONS_PER_YEAR * daily_results["turnover"].mean()) if n_sessions else None,
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def realized_moments(daily):
    if daily.empty:
        return {"fourth_central_moment": None, "pearson_kurtosis": None}
    if daily.nunique() == 1:
        return {"fourth_central_moment": 0.0, "pearson_kurtosis": None}
    squared = (daily - daily.mean()) ** 2
    second = float(squared.mean())
    fourth = float((squared ** 2).mean())
    return {"fourth_central_moment": fourth, "pearson_kurtosis": fourth / second ** 2 if second > 0 else None}


def report(label, daily_results, cash_returns, split):
    periods = {
        "is": daily_results.loc[daily_results.index < split],
        "oos": daily_results.loc[daily_results.index >= split],
        "full": daily_results,
    }
    output = {name: metrics(period, cash_returns) for name, period in periods.items()}
    for period, values in output.items():
        print(f"{label} {period.upper()}: {json.dumps(values, allow_nan=False)}")
    for period, values in periods.items():
        moments = realized_moments(values["return"])
        print(f"REALIZED_MOMENTS {label} {period.upper()}: {json.dumps(moments, allow_nan=False)}")
    return output


def main():
    config = load_config()
    universe = config["universe"]
    cash_ticker = config["risk_free_ticker"]
    prices, fetched_at = load_prices(
        [*universe, cash_ticker], config["download_start"], config["end"],
        config, str(ROOT / "config.yaml"),
    )
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print(f"PRICE_ADJUSTMENT: {PRICE_ADJUSTMENT}")
    daily_returns = prices.pct_change(fill_method=None).iloc[1:]
    asset_returns = daily_returns[universe]
    cash_returns = daily_returns[cash_ticker]
    start, split = config["backtest_start"], config["oos_start"]
    strategy_penalty = config["fourth_moment_penalty"]
    penalties = tuple(dict.fromkeys((strategy_penalty, 0.0)))
    targets_by_penalty, benchmark_targets = build_targets(asset_returns, config, penalties)
    print(f"PARAM_COMBOS_TRIED: {len(penalties)}")
    cost_rate = (config["cost_bps"] + config["slippage_bps"]) / 10_000
    cash_buffer_rate = config["cash_buffer_bps"] / 10_000
    closes = prices[universe]
    results_by_penalty = {
        penalty: simulate(closes, targets, start, cost_rate, cash_buffer_rate)
        for penalty, targets in targets_by_penalty.items()
    }
    strategy_results = results_by_penalty[strategy_penalty]
    if strategy_results.empty:
        raise ValueError("There are no trading sessions in the requested backtest period.")
    benchmark_results = simulate(closes, benchmark_targets, start, cost_rate, cash_buffer_rate)
    strategy_report = report("STRATEGY", strategy_results, cash_returns, split)
    benchmark_report = report("BENCHMARK_EQUAL_WEIGHT", benchmark_results, cash_returns, split)
    report("CONTROL_MIN_VARIANCE", results_by_penalty[0.0], cash_returns, split)
    output = {
        "strategy": config["strategy"],
        "data_range": f"{strategy_results.index[0].date()} to {strategy_results.index[-1].date()}",
        **strategy_report,
        "benchmark": benchmark_report["full"],
    }
    print("RESULTS_JSON: " + json.dumps(output, allow_nan=False))


if __name__ == "__main__":
    main()
